WITH exploded AS (SELECT id, plan, effective_from, currency, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) x AS val), with_windows AS (SELECT *, MIN(val) OVER (PARTITION BY plan) AS plan_min_val, RANK() OVER (PARTITION BY currency ORDER BY val NULLS FIRST) AS val_rank, RANK() OVER (PARTITION BY plan, currency ORDER BY val DESC) AS val_rank_2 FROM exploded WHERE effective_from <= '2025-05-01'), metrics AS (SELECT *, STDDEV_SAMP(val_rank_2) OVER (PARTITION BY MONTH(effective_from), plan) AS effective_from_month_stddev_samp_val_rank_2, MIN(val) OVER (PARTITION BY plan, currency) AS plan_min_val_2, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY val NULLS LAST) AS val_percent_rank, RANK() OVER (PARTITION BY plan, currency ORDER BY plan_min_val DESC NULLS FIRST) AS plan_min_val_rank FROM with_windows), valid AS (SELECT id, plan, effective_from, val, plan_min_val, val_rank, val_rank_2, effective_from_month_stddev_samp_val_rank_2, plan_min_val_2, val_percent_rank, plan_min_val_rank, ADD_MONTHS(effective_from, 12) AS effective_from_plus_months FROM metrics WHERE plan_min_val = 33) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, PERCENTILE_APPROX(plan_min_val_rank, 0.5) AS plan_min_val_rank_p50, COUNT(DISTINCT plan) AS distinct_plans, MAX(plan_min_val) FILTER (WHERE plan = 'basic') AS basic_max_plan_min_val FROM valid GROUP BY ROLLUP (DATE_TRUNC('QUARTER', effective_from)) ORDER BY distinct_plans DESC
